package com.nexamart.backend.domain;
import jakarta.persistence.*;
@Entity @Table(name="addresses") public class Address{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private UserAccount customer;private String label;private String recipientName;private String phone;@Column(length=1000)private String addressLine;private String city;private String state;private String postalCode;private Double latitude;private Double longitude;private boolean defaultAddress;public Long getId(){return id;}public UserAccount getCustomer(){return customer;}public void setCustomer(UserAccount v){customer=v;}public String getLabel(){return label;}public void setLabel(String v){label=v;}public String getRecipientName(){return recipientName;}public void setRecipientName(String v){recipientName=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getAddressLine(){return addressLine;}public void setAddressLine(String v){addressLine=v;}public String getCity(){return city;}public void setCity(String v){city=v;}public String getState(){return state;}public void setState(String v){state=v;}public String getPostalCode(){return postalCode;}public void setPostalCode(String v){postalCode=v;}public Double getLatitude(){return latitude;}public void setLatitude(Double v){latitude=v;}public Double getLongitude(){return longitude;}public void setLongitude(Double v){longitude=v;}public boolean isDefaultAddress(){return defaultAddress;}public void setDefaultAddress(boolean v){defaultAddress=v;}}
